p='src/strings.js'
s=open(p,encoding='utf8').read()
s=s.replace("  throw new Error('not implemented');","""  return String(text)
    .replace(/[đĐ]/g, 'd')
    .normalize('NFD')
    .replace(/[\\u0300-\\u036f]/g, '')
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, '-')
    .replace(/^-+/, '')
    .slice(0, 50)
    .replace(/-+$/, '');""")
open(p,'w',encoding='utf8').write(s)
p='test/strings.test.js'
s=open(p,encoding='utf8').read()
s=s.replace("{ capitalize }","{ capitalize, slugify }")
s+="""
test('slugify basic', () => assert.strictEqual(slugify('Hello, World!'), 'hello-world'));
test('slugify Vietnamese', () => assert.strictEqual(slugify('Đường Nguyễn Huệ'), 'duong-nguyen-hue'));
test('slugify trims hyphens and collapses runs', () => assert.strictEqual(slugify('  --a  &&  b--  '), 'a-b'));
test('slugify empty result', () => assert.strictEqual(slugify('!!!'), ''));
test('slugify truncates to 50 without trailing hyphen', () => {
  const out = slugify('a'.repeat(49) + ' bcd');
  assert.strictEqual(out, 'a'.repeat(49));
  assert.strictEqual(slugify('word '.repeat(30)).length <= 50, true);
  assert.strictEqual(slugify('a'.repeat(60)).length, 50);
});
"""
open(p,'w',encoding='utf8').write(s)
E
npm test 2>&1 | tail -12

